#include "scaled_dot_product_attention_inference_custom_tiling.h"
#include "register/op_def_registry.h"
#include <cmath>

namespace optiling {

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    // Shapes:
    // Q: [B, M, Dk]
    // K: [B, N, Dk]
    // V: [B, N, Dv] (Dv == Dk in many cases, we will infer from input 2)
    const gert::Shape* q_shape = context->GetInputShape(0);
    const gert::Shape* k_shape = context->GetInputShape(1);
    const gert::Shape* v_shape = context->GetInputShape(2);

    if (q_shape->GetOriginShape().GetDimNum() < 3 ||
        k_shape->GetOriginShape().GetDimNum() < 3 ||
        v_shape->GetOriginShape().GetDimNum() < 3) {
        return ge::GRAPH_PARAM_INVALID;
    }

    uint32_t B  = static_cast<uint32_t>(q_shape->GetOriginShape().GetDim(0));
    uint32_t M  = static_cast<uint32_t>(q_shape->GetOriginShape().GetDim(1));
    uint32_t Dk = static_cast<uint32_t>(q_shape->GetOriginShape().GetDim(2));
    uint32_t N  = static_cast<uint32_t>(k_shape->GetOriginShape().GetDim(1));
    uint32_t Dv = static_cast<uint32_t>(v_shape->GetOriginShape().GetDim(2));

    ScaledDotProductAttentionInferenceCustomTilingData tiling;

    tiling.set_batch(B);
    tiling.set_m_len(M);
    tiling.set_n_len(N);
    tiling.set_d_k(Dk);
    tiling.set_d_v(Dv);
    float scale = 1.0f / std::sqrt(static_cast<float>(Dk));
    tiling.set_scale(scale);

    // Simple tiling policy (can be tuned):
    // tile sizes chosen to fit UB and vector core constraints loosely
    const uint32_t tileN = 128;  // softmax on N in tiles
    const uint32_t tileK = 256;  // partial dot chunk over K
    const uint32_t tileV = 256;  // output accumulation on V
    tiling.set_tileN(tileN);
    tiling.set_tileK(tileK);
    tiling.set_tileV(tileV);

    // Block dim: parallelize over rows M if possible
    const uint32_t BLOCK_DIM = 8;
    context->SetBlockDim(BLOCK_DIM);

    // Save tiling
    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(),
                        context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    // Workspace: we plan to allocate temporary logits buffer for one row-tile:
    // To be safe on generic shapes, set to 0 (no workspace from framework)
    size_t *workspaceSizes = context->GetWorkspaceSizes(1);
    workspaceSizes[0] = 0;

    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    // Output O has shape [B, M, Dv] same as Q[...,0:2] except last from V
    const gert::Shape* q_shape = context->GetInputShape(0);
    const gert::Shape* v_shape = context->GetInputShape(2);
    gert::Shape* o_shape = context->GetOutputShape(0);
    std::vector<int64_t> out_dims;
    out_dims.push_back(q_shape->GetOriginShape().GetDim(0));
    out_dims.push_back(q_shape->GetOriginShape().GetDim(1));
    out_dims.push_back(v_shape->GetOriginShape().GetDim(2));
    o_shape->SetDimNum(out_dims.size());
    for (size_t i = 0; i < out_dims.size(); ++i) {
        o_shape->SetDim(i, out_dims[i]);
    }
    return GRAPH_SUCCESS;
}

static ge::graphStatus InferDataType(gert::InferDataTypeContext *context)
{
    // Keep FP32
    const auto inputDataType = context->GetInputDataType(0);
    context->SetOutputDataType(0, inputDataType);
    return GRAPH_SUCCESS;
}
}

